import { cacheLife, cacheTag } from 'next/cache'
import { getAllProducts } from './db'

// Shared, cached catalog query. Every view that reads products should go
// through this so a single `revalidateTag('products', ...)` refreshes them all.
export async function getProducts() {
  'use cache'
  cacheTag('products')
  cacheLife('max')

  return getAllProducts()
}

